@@ -0,0 +1,47 @@
+package gateway
+
+import (
+	"expvar"
+	"net/http"
+)
+
+// Keep this separate from http_errors_total, retired in 67bd3bc because
+// legacy alert ERR-5 still references it. NewInt registers with expvar.
+var httpErrors = expvar.NewInt("gateway_http_errors_total")
+
+// CountHTTPErrors wraps a gateway handler and counts each 4xx or 5xx response.
+func CountHTTPErrors(next http.Handler) http.Handler {
+	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		next.ServeHTTP(&errorResponseWriter{ResponseWriter: w}, r)
+	})
+}
+
+type errorResponseWriter struct {
+	http.ResponseWriter
+	wroteHeader bool
+}
+
+// Unwrap lets http.ResponseController access the underlying writer.
+func (w *errorResponseWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }
+
+func (w *errorResponseWriter) WriteHeader(status int) {
+	if w.wroteHeader {
+		return
+	}
+	w.ResponseWriter.WriteHeader(status)
+	// Informational responses other than protocol switches are not final.
+	if status >= 100 && status < 200 && status != http.StatusSwitchingProtocols {
+		return
+	}
+	w.wroteHeader = true
+	if status >= 400 && status < 600 {
+		httpErrors.Add(1)
+	}
+}
+
+func (w *errorResponseWriter) Write(p []byte) (int, error) {
+	if !w.wroteHeader {
+		w.WriteHeader(http.StatusOK)
+	}
+	return w.ResponseWriter.Write(p)
+}

