+package gateway
+
+import "net/http"
+
+// Counter is a registered counter whose Inc method is safe for concurrent use.
+type Counter interface {
+	Inc()
+}
+
+// Registry registers the gateway counter in the caller's metrics registry.
+// An adapter is needed if the registry uses a different registration API.
+type Registry interface {
+	RegisterCounter(name, help string) Counter
+}
+
+// Metrics holds the gateway's registered metrics.
+type Metrics struct {
+	httpErrors Counter
+}
+
+// NewMetrics registers metrics once, before serving requests.
+func NewMetrics(registry Registry) *Metrics {
+	// Do not reuse http_errors_total: 3b17a27 retired it because the legacy
+	// ERR-5 alert still reads that name (see monitoring/alerts.yaml).
+	return &Metrics{httpErrors: registry.RegisterCounter(
+		"gateway_http_errors_total", "Gateway 4xx and 5xx responses",
+	)}
+}
+
+// Handler counts each completed 4xx or 5xx response once.
+func (m *Metrics) Handler(next http.Handler) http.Handler {
+	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		response := &responseStatus{ResponseWriter: w}
+		next.ServeHTTP(response, r)
+		if response.status >= 400 && response.status < 600 {
+			m.httpErrors.Inc()
+		}
+	})
+}
+
+type responseStatus struct {
+	http.ResponseWriter
+	status int
+}
+
+func (w *responseStatus) WriteHeader(status int) {
+	w.ResponseWriter.WriteHeader(status)
+	// Informational responses other than a protocol switch are not final.
+	if w.status == 0 && (status == http.StatusSwitchingProtocols || status >= 200) {
+		w.status = status
+	}
+}
+
+func (w *responseStatus) Write(body []byte) (int, error) {
+	if w.status == 0 {
+		w.WriteHeader(http.StatusOK)
+	}
+	return w.ResponseWriter.Write(body)
+}
+
+// Unwrap lets http.ResponseController access the underlying writer.
+func (w *responseStatus) Unwrap() http.ResponseWriter {
+	return w.ResponseWriter
+}

