@@ -0,0 +1,61 @@
+package gateway
+
+import "net/http"
+
+// ErrorCounter is the increment operation supplied by the metrics registry.
+type ErrorCounter interface {
+	Inc()
+}
+
+// CounterRegistry connects gateway instrumentation to the serving application's
+// registry. Registered counters must support concurrent increments.
+type CounterRegistry interface {
+	RegisterCounter(name, help string) ErrorCounter
+}
+
+// NewMetricsHandler registers the gateway error counter once, at handler setup,
+// and counts each completed 4xx or 5xx response from next.
+func NewMetricsHandler(registry CounterRegistry, next http.Handler) http.Handler {
+	// http_errors_total was deliberately retired in commit 2f8cfce; ERR-5
+	// still references it. Keep this gateway metric under its own name.
+	errors := registry.RegisterCounter("gateway_http_errors_total", "Gateway 4xx and 5xx responses")
+	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		response := &metricsResponseWriter{ResponseWriter: w, status: http.StatusOK}
+		next.ServeHTTP(response, r)
+		if response.status >= 400 && response.status < 600 {
+			errors.Inc()
+		}
+	})
+}
+
+type metricsResponseWriter struct {
+	http.ResponseWriter
+	status      int
+	wroteHeader bool
+}
+
+func (w *metricsResponseWriter) WriteHeader(status int) {
+	if w.wroteHeader {
+		return
+	}
+	w.ResponseWriter.WriteHeader(status)
+	// Informational responses may precede the final response. Switching
+	// protocols is terminal, even though its status is in the 1xx range.
+	if status >= 100 && status < 200 && status != http.StatusSwitchingProtocols {
+		return
+	}
+	w.status = status
+	w.wroteHeader = true
+}
+
+func (w *metricsResponseWriter) Write(body []byte) (int, error) {
+	if !w.wroteHeader {
+		w.WriteHeader(http.StatusOK)
+	}
+	return w.ResponseWriter.Write(body)
+}
+
+// Unwrap allows http.ResponseController to access the underlying writer.
+func (w *metricsResponseWriter) Unwrap() http.ResponseWriter {
+	return w.ResponseWriter
+}
