+package gateway
+
+import (
+	"net/http"
+	"net/http/httptest"
+	"testing"
+)
+
+type recordingRegistry struct {
+	name          string
+	registrations int
+	count         int
+}
+
+func (r *recordingRegistry) RegisterCounter(name, help string) ErrorCounter {
+	r.name = name
+	r.registrations++
+	return r
+}
+
+func (r *recordingRegistry) Inc() { r.count++ }
+
+func TestMetricsHandlerStatusRange(t *testing.T) {
+	registry := &recordingRegistry{}
+	status := 200
+	handler := NewMetricsHandler(registry, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		w.WriteHeader(status)
+	}))
+	for status = 200; status <= 600; status++ {
+		before := registry.count
+		handler.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/", nil))
+		want := 0
+		if status >= 400 && status < 600 {
+			want = 1
+		}
+		if got := registry.count - before; got != want {
+			t.Fatalf("status %d: increments = %d, want %d", status, got, want)
+		}
+	}
+	if registry.registrations != 1 || registry.name != "gateway_http_errors_total" {
+		t.Fatalf("unexpected registration: %+v", registry)
+	}
+}
+
+func TestMetricsHandlerFinalStatus(t *testing.T) {
+	for _, tc := range []struct {
+		name  string
+		serve func(http.ResponseWriter)
+		want  int
+	}{
+		{"empty response", func(w http.ResponseWriter) {}, 0},
+		{"implicit success", func(w http.ResponseWriter) { w.Write([]byte("ok")); w.WriteHeader(500) }, 0},
+		{"first status wins", func(w http.ResponseWriter) { w.WriteHeader(404); w.WriteHeader(500); w.Write([]byte("missing")) }, 1},
+		{"informational then error", func(w http.ResponseWriter) { w.WriteHeader(103); w.WriteHeader(503) }, 1},
+		{"protocol switch", func(w http.ResponseWriter) { w.WriteHeader(101); w.WriteHeader(500) }, 0},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			registry := &recordingRegistry{}
+			handler := NewMetricsHandler(registry, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { tc.serve(w) }))
+			handler.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/", nil))
+			if registry.count != tc.want {
+				t.Fatalf("increments = %d, want %d", registry.count, tc.want)
+			}
+		})
+	}
+}

