@@ -0,0 +1,72 @@
+package gateway
+
+import "net/http"
+
+// Counter is a registry-owned counter. Inc must be safe for concurrent requests.
+type Counter interface {
+	Inc()
+}
+
+// Registry registers a counter with the gateway's existing metrics registry.
+// An adapter can implement this interface for the registry used by the caller.
+type Registry interface {
+	RegisterCounter(name, help string) (Counter, error)
+}
+
+// Metrics holds the counters shared by all handlers in a gateway.
+type Metrics struct {
+	errors Counter
+}
+
+// RegisterMetrics must be called once per gateway registry, before serving.
+func RegisterMetrics(registry Registry) (*Metrics, error) {
+	// Do not reuse http_errors_total: 2f8cfce retired it because the legacy
+	// ERR-5 alert still watches that name. This counter is gateway-specific.
+	counter, err := registry.RegisterCounter("gateway_http_errors_total", "Gateway 4xx and 5xx responses")
+	if err != nil {
+		return nil, err
+	}
+	return &Metrics{errors: counter}, nil
+}
+
+// Wrap counts each final 4xx or 5xx response once. Implicit 200s and later
+// ignored WriteHeader calls do not count. Wrap the outermost gateway handler.
+func (m *Metrics) Wrap(next http.Handler) http.Handler {
+	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		next.ServeHTTP(&responseWriter{ResponseWriter: w, errors: m.errors}, r)
+	})
+}
+
+type responseWriter struct {
+	http.ResponseWriter
+	errors      Counter
+	wroteHeader bool
+}
+
+// Unwrap allows http.ResponseController to reach the underlying writer.
+func (w *responseWriter) Unwrap() http.ResponseWriter {
+	return w.ResponseWriter
+}
+
+func (w *responseWriter) WriteHeader(status int) {
+	if w.wroteHeader {
+		return
+	}
+	w.ResponseWriter.WriteHeader(status)
+	// Informational responses do not commit the final response, except 101,
+	// which switches protocols and ends HTTP response processing.
+	if status >= 100 && status < 200 && status != http.StatusSwitchingProtocols {
+		return
+	}
+	w.wroteHeader = true
+	if status >= 400 && status < 600 {
+		w.errors.Inc()
+	}
+}
+
+func (w *responseWriter) Write(body []byte) (int, error) {
+	if !w.wroteHeader {
+		w.WriteHeader(http.StatusOK)
+	}
+	return w.ResponseWriter.Write(body)
+}
