+package gateway
+
+import (
+	"errors"
+	"net/http"
+	"net/http/httptest"
+	"testing"
+)
+
+type testCounter struct{ count int }
+
+func (c *testCounter) Inc() { c.count++ }
+
+type testRegistry struct {
+	name    string
+	counter testCounter
+	err     error
+}
+
+func (r *testRegistry) RegisterCounter(name, help string) (Counter, error) {
+	r.name = name
+	return &r.counter, r.err
+}
+
+func TestRegisterMetrics(t *testing.T) {
+	r := &testRegistry{}
+	if _, err := RegisterMetrics(r); err != nil {
+		t.Fatal(err)
+	}
+	if r.name != "gateway_http_errors_total" {
+		t.Fatalf("registered %q", r.name)
+	}
+	r.err = errors.New("registration failed")
+	if m, err := RegisterMetrics(r); m != nil || err != r.err {
+		t.Fatalf("registration failure: metrics=%v error=%v", m, err)
+	}
+}
+
+func TestResponseCounting(t *testing.T) {
+	for status := 200; status <= 599; status++ {
+		r := &testRegistry{}
+		m, err := RegisterMetrics(r)
+		if err != nil {
+			t.Fatal(err)
+		}
+		m.Wrap(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
+			w.WriteHeader(status)
+			w.WriteHeader(http.StatusInternalServerError)
+		})).ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/", nil))
+		want := 0
+		if status >= 400 {
+			want = 1
+		}
+		if r.counter.count != want {
+			t.Fatalf("status %d: count=%d, want %d", status, r.counter.count, want)
+		}
+	}
+}
+
+func TestImplicitSuccess(t *testing.T) {
+	r := &testRegistry{}
+	m, err := RegisterMetrics(r)
+	if err != nil {
+		t.Fatal(err)
+	}
+	m.Wrap(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
+		_, _ = w.Write([]byte("ok"))
+		w.WriteHeader(http.StatusInternalServerError)
+	})).ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/", nil))
+	if r.counter.count != 0 {
+		t.Fatalf("implicit 200 counted as an error: %d", r.counter.count)
+	}
+}
